import test from 'node:test';
import assert from 'node:assert/strict';
import { roundCents, formatEuros, parseEuros, RATES, convert, formatMoney } from '../src/money.js';

test('roundCents banker\'s rounding to even', () => {
  assert.equal(roundCents(124.5), 124);
  assert.equal(roundCents(125.5), 126);
  assert.equal(roundCents(2.4), 2);
  assert.equal(roundCents(2.6), 3);
  assert.equal(roundCents(-0.5), 0);
  assert.equal(roundCents(0.5), 0);
  assert.equal(roundCents(1.5), 2);
});

test('formatEuros basic amounts', () => {
  assert.equal(formatEuros(100), '€1.00');
  assert.equal(formatEuros(1000), '€10.00');
  assert.equal(formatEuros(123456), '€1,234.56');
});

test('formatEuros with cents', () => {
  assert.equal(formatEuros(1), '€0.01');
  assert.equal(formatEuros(50), '€0.50');
  assert.equal(formatEuros(99), '€0.99');
});

test('formatEuros negative', () => {
  assert.equal(formatEuros(-100), '-€1.00');
  assert.equal(formatEuros(-5), '-€0.05');
  assert.equal(formatEuros(-123456), '-€1,234.56');
});

test('parseEuros valid amounts', () => {
  assert.equal(parseEuros('100').value, 10000);
  assert.equal(parseEuros('1.5').value, 150);
  assert.equal(parseEuros('1234.56').value, 123456);
});

test('parseEuros with thousands separator', () => {
  assert.equal(parseEuros('1,234.56').value, 123456);
  assert.equal(parseEuros('1,000').value, 100000);
});

test('parseEuros invalid format', () => {
  assert.equal(parseEuros('invalid').ok, false);
  assert.equal(parseEuros('12.345').ok, false);
});

test('RATES constant defined', () => {
  assert.equal(RATES.EUR, 1);
  assert.equal(RATES.USD, 1.085);
  assert.equal(RATES.GBP, 0.8425);
});

test('convert EUR to EUR', () => {
  const result = convert(10000, 'EUR');
  assert.equal(result.ok, true);
  assert.equal(result.value, 10000);
});

test('convert EUR to USD', () => {
  const result = convert(10000, 'USD');
  assert.equal(result.ok, true);
  // 100 EUR * 1.085 = 108.5 USD = 10850 cents
  assert.equal(result.value, 10850);
});

test('convert EUR to GBP', () => {
  const result = convert(10000, 'GBP');
  assert.equal(result.ok, true);
  // 100 EUR * 0.8425 = 84.25 GBP = 8425 cents
  assert.equal(result.value, 8425);
});

test('convert zero amount', () => {
  assert.equal(convert(0, 'USD').value, 0);
  assert.equal(convert(0, 'GBP').value, 0);
  assert.equal(convert(0, 'EUR').value, 0);
});

test('convert with rounding', () => {
  const result = convert(1, 'USD');
  assert.equal(result.ok, true);
  // 0.01 EUR * 1.085 = 0.01085 USD = 1.085 cents, rounds to 1
  assert.equal(result.value, 1);
});

test('convert large amount', () => {
  const result = convert(1234567, 'USD');
  assert.equal(result.ok, true);
  // 12345.67 EUR * 1.085 = 13394.75195 USD = 1339475 cents (after rounding)
  assert.equal(result.value, 1339476);
});

test('convert unknown currency returns error', () => {
  const result = convert(10000, 'JPY');
  assert.equal(result.ok, false);
  assert.equal(result.error, 'UNKNOWN_CURRENCY');
});

test('convert with null or undefined currency', () => {
  const result1 = convert(10000, null);
  assert.equal(result1.ok, false);
  assert.equal(result1.error, 'UNKNOWN_CURRENCY');

  const result2 = convert(10000, undefined);
  assert.equal(result2.ok, false);
  assert.equal(result2.error, 'UNKNOWN_CURRENCY');
});

test('formatMoney EUR', () => {
  assert.equal(formatMoney(100, 'EUR'), '€1.00');
  assert.equal(formatMoney(123456, 'EUR'), '€1,234.56');
  assert.equal(formatMoney(1, 'EUR'), '€0.01');
});

test('formatMoney USD', () => {
  assert.equal(formatMoney(100, 'USD'), '$1.00');
  assert.equal(formatMoney(123456, 'USD'), '$1,234.56');
  assert.equal(formatMoney(1, 'USD'), '$0.01');
});

test('formatMoney GBP', () => {
  assert.equal(formatMoney(100, 'GBP'), '£1.00');
  assert.equal(formatMoney(123456, 'GBP'), '£1,234.56');
  assert.equal(formatMoney(1, 'GBP'), '£0.01');
});

test('formatMoney with thousands separator', () => {
  assert.equal(formatMoney(1000000, 'USD'), '$10,000.00');
  assert.equal(formatMoney(9999999, 'GBP'), '£99,999.99');
  assert.equal(formatMoney(12345678, 'EUR'), '€123,456.78');
});

test('formatMoney negative amounts', () => {
  assert.equal(formatMoney(-100, 'USD'), '-$1.00');
  assert.equal(formatMoney(-123456, 'GBP'), '-£1,234.56');
  assert.equal(formatMoney(-5, 'EUR'), '-€0.05');
});

test('formatMoney zero', () => {
  assert.equal(formatMoney(0, 'USD'), '$0.00');
  assert.equal(formatMoney(0, 'GBP'), '£0.00');
  assert.equal(formatMoney(0, 'EUR'), '€0.00');
});

test('formatMoney unknown currency uses code', () => {
  assert.equal(formatMoney(100, 'JPY'), 'JPY1.00');
  assert.equal(formatMoney(100, 'CHF'), 'CHF1.00');
});

test('convert and format round-trip EUR to USD', () => {
  // 100 EUR in cents
  const eurCents = 10000;
  const usdCents = convert(eurCents, 'USD').value;
  const formatted = formatMoney(usdCents, 'USD');
  assert.equal(formatted, '$108.50');
});

test('convert and format round-trip EUR to GBP', () => {
  // 100 EUR in cents
  const eurCents = 10000;
  const gbpCents = convert(eurCents, 'GBP').value;
  const formatted = formatMoney(gbpCents, 'GBP');
  assert.equal(formatted, '£84.25');
});

test('convert multiple currencies sequence', () => {
  const eurCents = 10000;
  const usd = convert(eurCents, 'USD').value;
  const gbp = convert(eurCents, 'GBP').value;

  assert(usd > eurCents); // USD stronger than EUR
  assert(gbp < eurCents); // GBP weaker than EUR
});

test('formatMoney with very large amounts', () => {
  assert.equal(formatMoney(999999999, 'USD'), '$9,999,999.99');
  assert.equal(formatMoney(1000000000, 'EUR'), '€10,000,000.00');
});

test('convert preserves integer cents', () => {
  const result = convert(12345, 'USD');
  assert(Number.isInteger(result.value));
});

test('formatMoney formats to 2 decimal places', () => {
  const result = formatMoney(12345, 'USD');
  // Should end with .45 (45 cents)
